import{_ as a,a0 as r,w as l,s as u,ao as x,I as s,x as n,a1 as e,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"Linux有问必答：如何显示Linux网桥的MAC学习表 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何显示Linux网桥的MAC学习表 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何显示Linux网桥的MAC学习表 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何显示Linux网桥的MAC学习表 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140825 Linux FAQs with Answers--How to show a MAC learning table of Linux bridge","title":"Linux有问必答：如何显示Linux网桥的MAC学习表","tag":"201410","desc":""},"relativePath":"201410/20140825 Linux FAQs with Answers--How to show a MAC learning table of Linux bridge.md","filePath":"[post].md"}'),p={name:"201410/20140825 Linux FAQs with Answers--How to show a MAC learning table of Linux bridge.md"};function L(d,t,m,C,A,f){const i=r("Link");return l(),u("div",null,[t[11]||(t[11]=x(`<h1 id="linux有问必答-如何显示linux网桥的mac学习表" tabindex="-1">Linux有问必答：如何显示Linux网桥的MAC学习表 <a class="header-anchor" href="#linux有问必答-如何显示linux网桥的mac学习表" aria-label="Permalink to “Linux有问必答：如何显示Linux网桥的MAC学习表”">​</a></h1><blockquote><p><strong>问题</strong>：我想要检查一下我用brctl工具创建的Linux网桥的MAC地址学习状态。请问，我要怎样才能查看Linux网桥的MAC学习表（或者转发表）？</p></blockquote><p>Linux网桥是网桥的软件实现，这是Linux内核的内核部分。与硬件网桥相类似，Linux网桥维护了一个2层转发表（也称为MAC学习表，转发数据库，或者仅仅称为FDB），它跟踪记录了MAC地址与端口的对应关系。当一个网桥在端口N收到一个包时（源MAC地址为X），它在FDB中记录为MAC地址X可以从端口N到达。这样的话，以后当网桥需要转发一个包到地址X时，它就可以从FDB查询知道转发到哪里。构建一个FDB常常称之为“MAC学习”或仅仅称为“学习”过程。</p><p>你可以使用以下命令来检查Linux网桥当前转发表或MAC学习表。</p><pre><code>$ sudo brctl showmacs &lt;bridge-name&gt;
</code></pre><p><img src="https://farm4.staticflickr.com/3856/14963353726_8971873948_z.jpg" alt=""></p><p>该命令将显示一个学习到的MAC地址与关联端口的列表。各个条目都有一个相关的附于其上的老化计时器，因此转发条目可以在一定时间后刷新，以使MAC学习表更新到最新。</p><hr>`,8)),s("p",null,[t[1]||(t[1]=n("via: ",-1)),e(i,{href:"http://ask.xmodulo.com/show-mac-learning-table-linux-bridge.html"},{default:o(()=>[...t[0]||(t[0]=[n("http://ask.xmodulo.com/show-mac-learning-table-linux-bridge.html",-1)])]),_:1})]),s("p",null,[t[4]||(t[4]=n("译者：",-1)),e(i,{href:"https://github.com/GOLinux"},{default:o(()=>[...t[2]||(t[2]=[n("GOLinux",-1)])]),_:1}),t[5]||(t[5]=n(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:o(()=>[...t[3]||(t[3]=[n("wxy",-1)])]),_:1})]),s("p",null,[t[8]||(t[8]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原创翻译，",-1)),e(i,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[n("Linux中国",-1)])]),_:1}),t[10]||(t[10]=n(" 荣誉推出",-1))])])}const T=a(p,[["render",L]]);export{w as __pageData,T as default};
